const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Approximate polygon covering Jianghan District, Wuhan (small central urban area)
    const geom = ee.Geometry.Polygon(
      [[[114.245, 30.585],
        [114.245, 30.635],
        [114.315, 30.635],
        [114.315, 30.585]]],
      null, false
    );

    const dateA = '2020-01-19';
    const dateB = '2020-02-04';

    const areaKm2 = ee.Number(geom.area(1)).divide(1e6).getInfo();
    console.log(`AOI area (km2): ${areaKm2.toFixed(2)}`);

    function pickFirstPresentBand(bandList, candidates) {
      for (let i = 0; i < candidates.length; i++) {
        if (bandList.indexOf(candidates[i]) !== -1) return candidates[i];
      }
      return null;
    }

    function safeGet(obj) {
      try { return obj.getInfo(); } catch (e) { return null; }
    }

    function getDailyStats(dateStr, label) {
      // Try daily Black Marble (VNP46A2)
      let result = {
        source: null, // 'daily' or 'monthly'
        dateStr: dateStr,
        window: null,
        images: 0,
        mean: null,
        validCount: 0,
        totalCount: 0,
        status: 'OK'
      };

      try {
        // exact day
        let start = ee.Date(dateStr);
        let end = start.advance(1, 'day');
        let col = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
          .filterBounds(geom)
          .filterDate(start, end);
        let size0 = col.size().getInfo();
        let windowNote = '±0d';
        // widen by ±1 day if empty
        if (size0 === 0) {
          const start2 = start.advance(-1, 'day');
          const end2 = start.advance(2, 'day');
          col = ee.ImageCollection('NOAA/VIIRS/001/VNP46A2')
            .filterBounds(geom)
            .filterDate(start2, end2);
          windowNote = '±1d';
        }
        const size = col.size().getInfo();
        if (size === 0) {
          // Fallback to monthly
          result.status = 'C1';
        } else {
          result.source = 'daily';
          result.window = windowNote;
          result.images = size;
          let img = col.median();

          const bandNames = img.bandNames().getInfo();
          const radBand = pickFirstPresentBand(bandNames || [], [
            'DNB_BRDF-Corrected_NTL', // common in VNP46A2
            'Gap_Filled_DNB_BRDF-Corrected_NTL',
            'Nadir_Radiance',
            'Radiance'
          ]);
          if (!radBand) {
            result.status = 'D';
            return result;
          }

          // Build mask: positive radiance and clear cloud if QF exists
          let rad = img.select(radBand);
          let mask = rad.gt(0);
          const qfBand = pickFirstPresentBand(bandNames || [], ['QF_Cloud_Mask', 'Cloud_Mask', 'Mandatory_Quality_Flag']);
          if (qfBand) {
            // Interpret 0 as clear for QF_Cloud_Mask-style bands
            const qf = img.select(qfBand);
            mask = mask.and(qf.eq(0));
          }
          rad = rad.updateMask(mask);

          const validCount = safeGet(
            rad.reduceRegion({
              reducer: ee.Reducer.count(),
              geometry: geom,
              scale: 1000,
              maxPixels: 1e9
            }).get(radBand)
          );
          if (validCount === null) {
            result.status = 'C3';
            return result;
          }
          result.validCount = validCount || 0;

          const totalCount = safeGet(
            ee.Image.constant(1).rename('ones').clip(geom).reduceRegion({
              reducer: ee.Reducer.count(),
              geometry: geom,
              scale: 1000,
              maxPixels: 1e9
            }).get('ones')
          );
          result.totalCount = totalCount || 0;

          if (result.validCount === 0) {
            result.status = 'C2';
            return result;
          }

          const mean = safeGet(
            rad.reduceRegion({
              reducer: ee.Reducer.mean(),
              geometry: geom,
              scale: 1000,
              maxPixels: 1e9
            }).get(radBand)
          );
          result.mean = mean;

          if (mean === null || isNaN(mean) || mean <= 0 || mean > 10000) {
            result.status = 'C3';
            return result;
          }
        }
      } catch (e) {
        // If dataset/band error, mark D to try monthly fallback next
        result.status = 'D';
      }
      return result;
    }

    function getMonthlyStats(monthStr) {
      // monthStr in 'YYYY-MM' (use for Jan and Feb 2020)
      let result = {
        source: 'monthly',
        month: monthStr,
        images: 0,
        mean: null,
        validCount: 0,
        totalCount: 0,
        status: 'OK'
      };
      try {
        const start = ee.Date(`${monthStr}-01`);
        const end = start.advance(1, 'month');
        let mcol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
          .filterBounds(geom)
          .filterDate(start, end);
        const msize = mcol.size().getInfo();
        result.images = msize;
        if (msize === 0) {
          result.status = 'C1';
          return result;
        }
        let mimg = ee.Image(mcol.first());
        const bands = mimg.bandNames().getInfo();
        const radBand = bands && bands.indexOf('avg_rad') !== -1 ? 'avg_rad' : null;
        if (!radBand) {
          result.status = 'D';
          return result;
        }
        const rad = mimg.select(radBand);

        const validCount = safeGet(
          rad.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geom,
            scale: 1000,
            maxPixels: 1e9
          }).get(radBand)
        );
        result.validCount = validCount || 0;

        const totalCount = safeGet(
          ee.Image.constant(1).rename('ones').clip(geom).reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geom,
            scale: 1000,
            maxPixels: 1e9
          }).get('ones')
        );
        result.totalCount = totalCount || 0;

        if (result.validCount === 0) {
          result.status = 'C2';
          return result;
        }

        const mean = safeGet(
          rad.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geom,
            scale: 1000,
            maxPixels: 1e9
          }).get(radBand)
        );
        result.mean = mean;
        if (mean === null || isNaN(mean) || mean <= 0 || mean > 10000) {
          result.status = 'C3';
          return result;
        }
      } catch (e) {
        result.status = 'D';
      }
      return result;
    }

    function printStats(label, res) {
      if (res.source === 'daily') {
        const validPct = res.totalCount > 0 ? (100 * res.validCount / res.totalCount) : 0;
        console.log(`${label} Daily VNP46A2 ${res.dateStr} images: ${res.images} (window ${res.window})`);
        console.log(`${label} Mean: ${res.mean !== null ? res.mean.toFixed(3) : 'null'}, Valid px: ${res.validCount}/${res.totalCount} (${validPct.toFixed(1)}%)`);
      } else if (res.source === 'monthly') {
        const validPct = res.totalCount > 0 ? (100 * res.validCount / res.totalCount) : 0;
        console.log(`${label} Monthly VCMSLCFG ${res.month} images: ${res.images}`);
        console.log(`${label} Mean: ${res.mean !== null ? res.mean.toFixed(3) : 'null'}, Valid px: ${res.validCount}/${res.totalCount} (${validPct.toFixed(1)}%)`);
      } else {
        console.log(`${label} Status: ${res.status}`);
      }
    }

    // Process A (Jan 19, 2020)
    let A = getDailyStats(dateA, 'A');
    if (A.status !== 'OK') {
      // Fallback to monthly for Jan 2020
      const Am = getMonthlyStats('2020-01');
      if (Am.status === 'OK') {
        A = { ...Am, source: 'monthly' };
      } else {
        printStats('A', A);
        console.log(Am.status);
        return;
      }
    }

    // Process B (Feb 4, 2020)
    let B = getDailyStats(dateB, 'B');
    if (B.status !== 'OK') {
      // Fallback to monthly for Feb 2020
      const Bm = getMonthlyStats('2020-02');
      if (Bm.status === 'OK') {
        B = { ...Bm, source: 'monthly' };
      } else {
        printStats('B', B);
        console.log(Bm.status);
        return;
      }
    }

    // Print concise evidence
    printStats('A', A);
    printStats('B', B);

    // Decision and failure handling
    function finalFailureTag(obj) {
      if (obj.status === 'C1') return 'C1';
      if (obj.status === 'C2') return 'C2';
      if (obj.status === 'C3') return 'C3';
      if (obj.status === 'D') return 'D';
      return null;
    }
    const failA = finalFailureTag(A);
    const failB = finalFailureTag(B);
    if (failA) { console.log(failA); return; }
    if (failB) { console.log(failB); return; }

    const meanA = A.mean;
    const meanB = B.mean;
    if (meanA === null || meanB === null || isNaN(meanA) || isNaN(meanB)) {
      console.log('C3');
      return;
    }

    // Compare: Was Feb 4 lower than Jan 19?
    const answer = (meanB < meanA) ? 'A' : 'B';
    console.log(answer);
  } catch (e) {
    // Any unexpected runtime issue
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
